int handle_futex_wait_requeue(u32 __user *uaddr, unsigned int flags, u32 val,
                              ktime_t *abs_time, u32 bitset, u32 __user *uaddr2)
{
    struct hrtimer timer;
    struct futex_waiter *waiter;
    int ret = -EINVAL;

    if (!uaddr || !uaddr2 || (flags & ~FUTEX_CMD_MASK))
        return -EINVAL;

    if (abs_time) {
        hrtimer_init(&timer, CLOCK_MONOTONIC, HRTIMER_MODE_ABS);
