    }

    waiter = kmalloc(sizeof(*waiter), GFP_KERNEL);
    if (!waiter)
        return -ENOMEM;

    waiter->bitset = bitset;
    waiter->flags = flags;

    ret = futex_wait(uaddr, flags, val, abs_time, waiter);
    if (ret < 0) {
        kfree(waiter);
        return ret;
    }

