int handle_futex_wait_requeue(u32 __user *uaddr, unsigned int flags, u32 val,
                              ktime_t *abs_time, u32 bitset, u32 __user *uaddr2) {
    int ret;
    struct hrtimer timer;
    struct futex_q q;
    union wait_bitq wq;

    if ((flags & FUTEX_PRIVATE_FLAG) == 0) {
        return -EINVAL;
    }

    if (abs_time) {
        hrtimer_init(&timer, CLOCK_MONOTONIC, HRTIMER_MODE_ABS);
        timer.function = futex_hrtimer_callback;
        ret = hrtimer_start(&timer, *abs_time, HRTIMER_MODE_ABS);
        if (ret) {
            return ret;
        }
    }

    futex_init_wait_queue(&wq, current);
    futex_init_q(&q, uaddr, val, bitset, flags, &wq);

    ret = futex_wait(&q);
    if (ret == 0) {
        ret = futex_requeue(uaddr2, bitset, &q);
    }

    if (abs_time) {
        hrtimer_cancel(&timer);
    }

    return ret;
}

