int futex_wait_requeue(u32 __user *uaddr, unsigned int flags, u32 val,
                       ktime_t *abs_time, u32 bitset, u32 __user *uaddr2) {
    struct hrtimer s_timer;
    struct hrtimer_sleeper timeout;
    int ret;

    if (abs_time) {
        hrtimer_init_sleeper(&timeout, &s_timer, HRTIMER_MODE_ABS);
        ret = hrtimer_start_sleeper(&timeout, *abs_time);
        if (ret)
            return ret;
    }

    ret = futex_wait(uaddr, flags, val, abs_time, bitset);
    if (ret)
        return ret;

    ret = futex_requeue(uaddr, flags, uaddr2);
    if (ret) {
        if (abs_time)
            hrtimer_cancel_sleeper(&timeout);
        return ret;
    }

    if (abs_time)
        hrtimer_cancel_sleeper(&timeout);

    return 0;
}

#include <linux/futex.h>
#include <linux/sched.h>
#include <linux/ktime.h>

int futex_wait_requeue_pi(u32 __user *uaddr, unsigned int flags, u32 val,
                          ktime_t *abs_time, u32 bitset, u32 __user *uaddr2)
{
    int ret = 0;
    struct hrtimer sht_timer;
    struct futex_q q = { };
    int timeout_set = 0;

    if (flags & FUTEX_PRIVATE_FLAG) {
        return -EINVAL;
    }

    if (abs_time) {
        hrtimer_init(&sht_timer, CLOCK_REALTIME, HRTIMER_MODE_ABS);
        sht_timer.function = futex_setup_timer;
        hrtimer_set_expires(&sht_timer, ktime_get());
        timeout_set = 1;
    }

    q.pi_state = NULL;
    q.bitset = bitset;
    q.requeue_pi_key = NULL;
    q.key = FUTEX_KEY_INIT;

    if (flags & FUTEX_REQUEUE_PI) {
        ret = futex_lock_pi(uaddr, flags, val, abs_time, &q, NULL);
    } else {
        ret = futex_wait(uaddr, flags, val, abs_time, bitset, &q);
    }

    if (ret == 0) {
        ret = futex_requeue(uaddr2, flags, val, bitset, &q);
    }

    if (timeout_set) {
        hrtimer_cancel(&sht_timer);
    }

    return ret;
}
